/**
 * Optional AI digest summariser.
 *
 * When the build carries `EXPO_PUBLIC_AI_API_KEY` (from `.env`, gitignored,
 * inlined by Metro at build time) the plain template digest is upgraded to a
 * short, natural-language summary generated by a hosted LLM (Anthropic or
 * OpenAI). Every failure path — no key, network error, bad status, empty
 * content — falls back to the template, so the digest never disappears and the
 * app keeps working with zero configuration.
 *
 * This module is the ONLY place that reads the key. It is never logged, never
 * persisted, and never sent anywhere except the provider's own endpoint.
 */

export type AiProvider = 'anthropic' | 'openai';

/** Inlined by Metro when `EXPO_PUBLIC_AI_API_KEY` is present in `.env`. */
const API_KEY = process.env.EXPO_PUBLIC_AI_API_KEY ?? '';
const PROVIDER: AiProvider = process.env.EXPO_PUBLIC_AI_PROVIDER === 'openai' ? 'openai' : 'anthropic';
const MODEL =
  process.env.EXPO_PUBLIC_AI_MODEL ??
  (PROVIDER === 'openai' ? 'gpt-4o-mini' : 'claude-3-5-haiku-latest');

/** Hard cap on the summary so a runaway generation stays notification-sized. */
const MAX_TOKENS = 220;
const TIMEOUT_MS = 12000;

/** True when this build was compiled with an AI key. */
export function aiDigestAvailable(): boolean {
  return API_KEY.length > 0;
}

/**
 * Ask the provider for a 2-3 sentence summary of the template digest. The
 * template is passed as the source of truth; the model must not invent data.
 * Returns null on any failure so callers fall back to the template.
 */
export async function summarizeDigest(
  templateBody: string,
  cityName: string,
  language: string,
): Promise<string | null> {
  if (!aiDigestAvailable()) return null;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  try {
    const request: { url: string; init: RequestInit } =
      PROVIDER === 'openai'
        ? {
            url: 'https://api.openai.com/v1/chat/completions',
            init: {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                Authorization: `Bearer ${API_KEY}`,
              },
              body: JSON.stringify({
                model: MODEL,
                max_tokens: MAX_TOKENS,
                messages: [
                  {
                    role: 'system',
                    content:
                      'You rewrite weather-digest facts into a warm, plain 2-3 sentence summary. ' +
                      'Use ONLY the facts given — never invent temperatures, rain, or times. ' +
                      'Reply in the same language as the facts. No markdown, no lists, no preamble.',
                  },
                  {
                    role: 'user',
                    content: `City: ${cityName}\nLanguage code: ${language}\nFacts:\n${templateBody}`,
                  },
                ],
              }),
            },
          }
        : {
            url: 'https://api.anthropic.com/v1/messages',
            init: {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'x-api-key': API_KEY,
                'anthropic-version': '2023-06-01',
              },
              body: JSON.stringify({
                model: MODEL,
                max_tokens: MAX_TOKENS,
                system:
                  'You rewrite weather-digest facts into a warm, plain 2-3 sentence summary. ' +
                  'Use ONLY the facts given — never invent temperatures, rain, or times. ' +
                  'Reply in the same language as the facts. No markdown, no lists, no preamble.',
                messages: [
                  {
                    role: 'user',
                    content: `City: ${cityName}\nLanguage code: ${language}\nFacts:\n${templateBody}`,
                  },
                ],
              }),
            },
          };

    const response = await fetch(request.url, {
      ...request.init,
      signal: controller.signal,
    });
    if (!response.ok) return null;

    const json = (await response.json()) as Record<string, unknown>;
    let text: string;
    if (PROVIDER === 'openai') {
      const choices = json.choices as { message?: { content?: string } }[] | undefined;
      text = choices?.[0]?.message?.content ?? '';
    } else {
      const content = json.content as { type?: string; text?: string }[] | undefined;
      text = content?.find((block) => block.type === 'text')?.text ?? '';
    }
    const summary = text.trim();
    return summary.length > 0 ? summary : null;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}
